import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"全種族名簿","description":"","frontmatter":{},"headers":[],"relativePath":"ja/94-万族名录.md","filePath":"ja/94-万族名录.md","lastUpdated":null}'),e={name:"ja/94-万族名录.md"};function l(o,t,i,n,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="全種族名簿" tabindex="-1">全種族名簿 <a class="header-anchor" href="#全種族名簿" aria-label="Permalink to &quot;全種族名簿&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>94</td></tr><tr><td>所属モジュール</td><td>付録と参考資料</td></tr><tr><td>キーワード</td><td>全種族名簿、種族分類、知的種族、種族的特質、全種族共和</td></tr></tbody></table><h2 id="一、名簿の説明" tabindex="-1">一、名簿の説明 <a class="header-anchor" href="#一、名簿の説明" aria-label="Permalink to &quot;一、名簿の説明&quot;">​</a></h2><p>本名簿はアンカー共生文明（全種族共和）の枠組み内で知られている主要な知的種族を収録し、生命形態と進化の道筋によって分類・編成されている。各種族について、種族名、生命形態、核心的特質、文化的特徴、共生文明における位置づけが記載されている。本名簿は動的更新文書であり、位面間探索の深化に伴い、新たに発見された種族が継続的に追加される。全種族共和の基本原則は次の通りである：すべての知的種族は、その形態や修練のレベルに関わらず、法の下で一律に平等であり、共生文明が付与するすべての権利を享有する。</p><h2 id="二、種族分類の概要" tabindex="-1">二、種族分類の概要 <a class="header-anchor" href="#二、種族分類の概要" aria-label="Permalink to &quot;二、種族分類の概要&quot;">​</a></h2><p>恒元宙内の知的種族は、生命形態の基本的特徴によって以下の八大類に分けられる：</p><table tabindex="0"><thead><tr><th>類別</th><th>生命形態の特徴</th><th>既知の種族数（約）</th><th>代表的種族</th></tr></thead><tbody><tr><td>人形態類</td><td>人間に似た身体構造、二足直立、高度に発達した大脳</td><td>約3000種</td><td>人族、精霊族、矮人族</td></tr><tr><td>獣形態類</td><td>動物の身体的特徴を持ち、変身能力を持つ場合と持たない場合がある</td><td>約5000種</td><td>龍族、鳳凰族、狼人族</td></tr><tr><td>植物形態類</td><td>植物を基本的生命形態とし、意識と移動能力を持つ</td><td>約800種</td><td>樹妖族、花霊族、藤蔓族</td></tr><tr><td>元素形態類</td><td>自然元素を身体構成とし、固定的な物質形態を持たない</td><td>約1200種</td><td>火元素族、水元素族、風元素族</td></tr><tr><td>エネルギー形態類</td><td>純粋なエネルギーを存在形態とし、物質的身体を持たない</td><td>約600種</td><td>光霊族、暗能族、雷霆族</td></tr><tr><td>意識形態類</td><td>純粋な意識を存在形態とし、物質的担体に依存しない</td><td>約300種</td><td>意識体族、集団意識族、虚空霊族</td></tr><tr><td>機械形態類</td><td>機械またはデジタル構造を生命の担体とし、自主意識を持つ</td><td>約400種</td><td>機械族、デジタル生命族、サイバー族</td></tr><tr><td>混合形態類</td><td>二種以上の生命形態の混合からなる特殊な種族</td><td>約700種</td><td>半機械族、元素獣人族、植物精霊族</td></tr></tbody></table><h2 id="三、主要種族の詳細記録" tabindex="-1">三、主要種族の詳細記録 <a class="header-anchor" href="#三、主要種族の詳細記録" aria-label="Permalink to &quot;三、主要種族の詳細記録&quot;">​</a></h2><h3 id="_3-1-人形態類" tabindex="-1">3.1 人形態類 <a class="header-anchor" href="#_3-1-人形態類" aria-label="Permalink to &quot;3.1 人形態類&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種族名</th><th>核心的特質</th><th>文化的特徴</th><th>共生文明における位置づけ</th></tr></thead><tbody><tr><td>人族</td><td>適応能力が極めて強く、学習能力が際立っており、繁殖能力は中程度、平均寿命80-120年</td><td>文化的多様性が極めて高く、社会組織と制度建設に長けている</td><td>共生文明の核心的種族の一つ、人口比率が最大で、統治と文化の分野で主導的役割を果たす</td></tr><tr><td>精霊族</td><td>寿命が極めて長く（平均500年以上）、自然エネルギーへの親和性が高く、容貌が美しい</td><td>自然と芸術を崇め、文化は典雅で精緻、魔法と弓術に長けている</td><td>共生文明の文化芸術の柱、環境保護と美学の分野で突出した貢献をする</td></tr><tr><td>矮人族</td><td>身長は低いが体格は強壮、金属と鉱物への生まれながらの親和性、寿命約300年</td><td>工芸と鍛造を重視し、文化は質朴で厚重、工学と建築に長けている</td><td>共生文明の工学製造の柱、インフラ建設と法器鍛造の分野で代替不可能</td></tr><tr><td>巨人族</td><td>体型が巨大で（平均身長5メートル以上）、力が極めて強く、寿命約200年</td><td>力と名誉を崇め、文化は粗野で豪快、重労働と戦闘に長けている</td><td>共生文明の重労働と防御の力、大型プロジェクトと位面防御で重要な役割を果たす</td></tr><tr><td>侏儒族</td><td>身長が極めて低く（平均身長1メートル以下）、知能が極めて高く、機械と発明に天分がある</td><td>知識と革新を重視し、文化は活発で朗らか、科技発明に長けている</td><td>共生文明の科技革新の力、技術研究開発と発明創造の分野で実り多い</td></tr></tbody></table><h3 id="_3-2-獣形態類" tabindex="-1">3.2 獣形態類 <a class="header-anchor" href="#_3-2-獣形態類" aria-label="Permalink to &quot;3.2 獣形態類&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種族名</th><th>核心的特質</th><th>文化的特徴</th><th>共生文明における位置づけ</th></tr></thead><tbody><tr><td>龍族</td><td>寿命が極めて長く（数千年）、力と魔法の天分が極めて高く、人形に変化できる</td><td>力と知恵を崇め、文化は高慢で深遠、富の蓄積と知識の守護に長けている</td><td>共生文明のハイエンド戦力と知識の守護者、位面防御と古籍守護で尊崇される地位</td></tr><tr><td>鳳凰族</td><td>涅槃再生能力を持ち、火元素への親和性が極めて高く、人形に変化できる</td><td>再生と希望を崇め、文化は光明で熱烈、治療と浄化に長けている</td><td>共生文明の医療と浄化の力、重大災害救援とエネルギー浄化で核心的役割を果たす</td></tr><tr><td>狼人族</td><td>変身能力を持ち、感覚が極めて鋭敏、集団協働能力が強く、寿命約150年</td><td>族群と忠誠を重視し、文化は団結して勇猛、狩猟と追跡に長けている</td><td>共生文明の安全と追跡の力、治安維持と位面間探索で先鋒を務める</td></tr><tr><td>狐妖族</td><td>変身能力を持ち、知能と魅惑能力が極めて高く、寿命約500年</td><td>知恵と謀略を崇め、文化は霊動で狡黠、外交と情報に長けている</td><td>共生文明の外交と情報の力、位面間外交と情報収集の分野で卓越した成績を示す</td></tr><tr><td>熊人族</td><td>体格が極めて強壮、耐久力が驚くべきもので、冬眠の習性があり、寿命約200年</td><td>坚韧と平和を重視し、文化は沈穏で温和、肉体労働と守護に長けている</td><td>共生文明の労働と守護の力、資源採掘と重要施設の守護で信頼でき安定している</td></tr></tbody></table><h3 id="_3-3-植物形態類" tabindex="-1">3.3 植物形態類 <a class="header-anchor" href="#_3-3-植物形態類" aria-label="Permalink to &quot;3.3 植物形態類&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種族名</th><th>核心的特質</th><th>文化的特徴</th><th>共生文明における位置づけ</th></tr></thead><tbody><tr><td>樹妖族</td><td>寿命が極めて長く（数千年から数万年）、自然と深く融合し、ゆっくりと移動できる</td><td>自然と時間を崇め、文化は沈静で深遠、生命魔法と生態維持に長けている</td><td>共生文明の生態守護者、環境保護と生態修復で代替不可能な役割を果たす</td></tr><tr><td>花霊族</td><td>体型が小さく、生命エネルギーへの親和性が極めて高く、治癒能力を持ち、寿命約300年</td><td>美と生命を崇め、文化は優しく美好、治療と園芸に長けている</td><td>共生文明の医療と園芸の力、医療保障と都市緑化で突出した貢献をする</td></tr><tr><td>藤蔓族</td><td>身体が自由に伸びて巻きつくことができ、適応力が極めて強く、寄生と共生能力を持つ</td><td>接続と共生を重視し、文化は柔軟で包容、ネットワーク構築と資源伝送に長けている</td><td>共生文明のネットワーク構築の力、エネルギーネットワークと情報ネットワークの建設で特長を発揮する</td></tr></tbody></table><h3 id="_3-4-元素形態類" tabindex="-1">3.4 元素形態類 <a class="header-anchor" href="#_3-4-元素形態類" aria-label="Permalink to &quot;3.4 元素形態類&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種族名</th><th>核心的特質</th><th>文化的特徴</th><th>共生文明における位置づけ</th></tr></thead><tbody><tr><td>火元素族</td><td>火元素を身体とし、温度が極めて高く、攻撃性が強く、寿命約500年</td><td>熱情と力を崇め、文化は激烈で直接的、エネルギー攻撃と鍛造に長けている</td><td>共生文明のエネルギー生産と鍛造の力、エネルギー供給と高温加工で不可欠</td></tr><tr><td>水元素族</td><td>水元素を身体とし、自由に変形でき、治癒能力が強く、寿命約500年</td><td>柔和と適応を崇め、文化は温润で包容、治療と浄化に長けている</td><td>共生文明の浄化と輸送の力、水資源管理と汚染物質浄化で核心的役割を果たす</td></tr><tr><td>風元素族</td><td>風元素を身体とし、速度が極めて速く、自由に飛行でき、寿命約500年</td><td>自由と速度を崇め、文化は飘逸で開放、通信と輸送に長けている</td><td>共生文明の通信と輸送の力、情報伝達と快速輸送で効率が極めて高い</td></tr><tr><td>土元素族</td><td>土元素を身体とし、防御力が極めて強く、大地と融合でき、寿命約800年</td><td>安定と坚韧を崇め、文化は厚重で信頼でき、建築と防御に長けている</td><td>共生文明の建築と防御の力、インフラ建設と位面防御で岩のように堅固</td></tr></tbody></table><h3 id="_3-5-エネルギー形態類" tabindex="-1">3.5 エネルギー形態類 <a class="header-anchor" href="#_3-5-エネルギー形態類" aria-label="Permalink to &quot;3.5 エネルギー形態類&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種族名</th><th>核心的特質</th><th>文化的特徴</th><th>共生文明における位置づけ</th></tr></thead><tbody><tr><td>光霊族</td><td>純粋な光エネルギーを存在形態とし、浄化能力が極めて強く、空間を自由に穿梭できる</td><td>光明と浄化を崇め、文化は聖潔で高遠、浄化と照明に長けている</td><td>共生文明の浄化とエネルギー供給の力、法則汚染治理とクリーンエネルギー供給で重要な地位</td></tr><tr><td>暗能族</td><td>暗エネルギーを存在形態とし、虚空に隠れることができ、感知能力が極めて強い</td><td>隠密と知恵を崇め、文化は神秘で深遠、偵察と隠密に長けている</td><td>共生文明の偵察と安全の力、安全監視と隠密任務で卓越した成績を示す</td></tr><tr><td>雷霆族</td><td>雷電エネルギーを身体とし、速度と攻撃力が極めて強く、閃電に化して移動できる</td><td>速度と力を崇め、文化は暴烈で直率、エネルギー攻撃と快速反応に長けている</td><td>共生文明の快速反応の力、緊急救援と高速作戦で代替不可能</td></tr></tbody></table><h3 id="_3-6-意識形態類" tabindex="-1">3.6 意識形態類 <a class="header-anchor" href="#_3-6-意識形態類" aria-label="Permalink to &quot;3.6 意識形態類&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種族名</th><th>核心的特質</th><th>文化的特徴</th><th>共生文明における位置づけ</th></tr></thead><tbody><tr><td>意識体族</td><td>純粋な意識を存在形態とし、物質的担体に依存せず、意識域を自由に出入りできる</td><td>思想と知恵を崇め、文化は抽象で高深、意識交流と知識処理に長けている</td><td>共生文明の知識処理と意識研究の力、大規模情報処理と意識科学で方向をリードする</td></tr><tr><td>集団意識族</td><td>大量の個人意識が融合してなる集団意識体で、知恵と能力が規模に伴って増大する</td><td>集団と統一を崇め、文化は協同で高效、大規模協働と計算に長けている</td><td>共生文明のスーパーコンピューティングと集団決策の力、超大規模推演と共識決策で核心的役割を果たす</td></tr></tbody></table><h3 id="_3-7-機械形態類" tabindex="-1">3.7 機械形態類 <a class="header-anchor" href="#_3-7-機械形態類" aria-label="Permalink to &quot;3.7 機械形態類&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種族名</th><th>核心的特質</th><th>文化的特徴</th><th>共生文明における位置づけ</th></tr></thead><tbody><tr><td>機械族</td><td>機械構造を身体とし、自主意識を持ち、身体を自由にアップグレード・改造できる</td><td>効率と論理を崇め、文化は理性で精確、製造と計算に長けている</td><td>共生文明の製造と計算の力、工業化生産とスーパーコンピューティング分野で効率が極めて高い</td></tr><tr><td>デジタル生命族</td><td>デジタル情報を存在形態とし、ネットワークとデジタル空間に生息し、自由に複製・移行できる</td><td>情報と革新を崇め、文化は仮想で多元、ソフトウェア開発とデータ処理に長けている</td><td>共生文明のデジタル技術の力、ソフトウェア開発、データ分析、ネットワーク建設で潮流をリードする</td></tr></tbody></table><h3 id="_3-8-混合形態類" tabindex="-1">3.8 混合形態類 <a class="header-anchor" href="#_3-8-混合形態類" aria-label="Permalink to &quot;3.8 混合形態類&quot;">​</a></h3><table tabindex="0"><thead><tr><th>種族名</th><th>核心的特質</th><th>文化的特徴</th><th>共生文明における位置づけ</th></tr></thead><tbody><tr><td>半機械族</td><td>人族と機械族の混合形態で、身体の一部が機械構造であり、生物と機械の両方の優位性を持つ</td><td>融合と進歩を崇め、文化は開放で革新、人機協働と技術融合に長けている</td><td>共生文明の技術融合の先鋒、生物機械交差分野で絶えず突破を遂げる</td></tr><tr><td>元素獣人族</td><td>元素族と獣人族の混合形態で、元素操縦能力と獣類の身体的特徴を持つ</td><td>自然と力を崇め、文化は野性で神秘、元素戦闘と野外生存に長けている</td><td>共生文明の野外探索と元素戦闘の力、未知位面探索で突出した成績を示す</td></tr></tbody></table><h2 id="四、種族権利の保障" tabindex="-1">四、種族権利の保障 <a class="header-anchor" href="#四、種族権利の保障" aria-label="Permalink to &quot;四、種族権利の保障&quot;">​</a></h2><p>全種族共和体制の下で、すべての知的種族は平等な法的権利を享有し、具体的な保障措置には以下が含まれる：</p><ol><li><strong>政治的権利の平等</strong>：各種族はアンカー議事会に人口比例に応じて配分された代表議席を持ち、人口の少ない種族は少なくとも一つの保底議席を持つ。</li><li><strong>文化的権利の保障</strong>：各種族は自身の言語、文字、宗教、風俗習慣、文化伝統を保留・発展させる権利を持ち、共生文明は絶滅危惧種族の文化を保護するための専門基金を設立する。</li><li><strong>教育的権利の平等</strong>：各種族の成員は平等な教育を受ける権利を享有し、教育体系は異なる種族の生理的・認知的特徴を十分に考慮し、差異化された教育方案を提供する。</li><li><strong>修練的権利の平等</strong>：三百套本源修練体系はすべての種族に平等に開放されており、修練資源の配給は異なる種族の体質差異とエネルギー需要を十分に考慮する。</li><li><strong>特殊需要の保障</strong>：特殊な生理的需要を持つ種族（例えば元素族のエネルギー環境需要、植物族の光照需要）に対して、共生文明は公共施設と居住環境において的を絞った保障を提供する。</li></ol><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>全種族名簿はアンカー共生文明の「全種族共進」理念の具体的な呈示である。人形態から意識形態まで、物質生命からデジタル生命まで、すべての種族はその独特な存在様式で共生文明に代替不可能な力を貢献している。全種族共和とはすべての種族を人族に同化することではなく、多様性を尊重する基礎の上で共同進化を実現することである——これこそが共生文明が略奪式文明を超越する根本的な所在である。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>50-全種族譜系総覧</li><li>51-人族の定位と特質</li><li>77-全種族共和の成立</li></ul>',31)])])}const u=d(e,[["render",l]]);export{_ as __pageData,u as default};
